#include <algorithm>
#include <cstdint>
#include <fstream>
#include <functional>
#include <iostream>
#include <numeric>
#include <stdexcept>
#include <vector>
using U=uint64_t; using I=int64_t;
void ck(bool b,const char*s){if(!b)throw std::runtime_error(s);}
std::vector<unsigned> decode(int n,unsigned code){std::vector<unsigned>a(n);for(int i=0;i<n;i++)for(int j=i+1;j<n;j++){if(code&1)a[i]|=1u<<j;else a[j]|=1u<<i;code>>=1;}return a;}
std::vector<unsigned> blow(const std::vector<unsigned>&q){int k=q.size();std::vector<unsigned>a(3*k);for(int i=0;i<k;i++)for(int r=0;r<3;r++){a[3*i+r]|=1u<<(3*i+(r+1)%3);for(int j=0;j<k;j++)if(q[i]>>j&1)a[3*i+r]|=7u<<(3*j);}return a;}
U count(const std::vector<unsigned>&a){int n=a.size();unsigned N=1u<<n;std::vector<U>E(size_t(N)*n);std::vector<unsigned>in(n);for(int i=0;i<n;i++){E[(1u<<i)*n+i]=1;for(int j=0;j<n;j++)if(a[j]>>i&1)in[i]|=1u<<j;}for(unsigned M=1;M<N;M++){unsigned is=M;while(is){int i=__builtin_ctz(is);is&=is-1;unsigned P=M^(1u<<i);if(!P)continue;U v=0;unsigned js=P&in[i];while(js){int j=__builtin_ctz(js);js&=js-1;v+=E[size_t(P)*n+j];}E[size_t(M)*n+i]=v;}}U h=0;for(int i=0;i<n;i++)h+=E[size_t(N-1)*n+i];return h;}
struct Field{int n; U h; std::vector<I>C,A;};
Field field(const std::vector<unsigned>&a){int n=a.size();unsigned N=1u<<n;std::vector<U>E(size_t(N)*n),S(size_t(N)*n),Q(size_t(n)*n);std::vector<unsigned>in(n);for(int i=0;i<n;i++){E[(1u<<i)*n+i]=S[(1u<<i)*n+i]=1;for(int j=0;j<n;j++)if(a[j]>>i&1)in[i]|=1u<<j;}for(unsigned M=1;M<N;M++){unsigned is=M;while(is){int i=__builtin_ctz(is);is&=is-1;unsigned P=M^(1u<<i);if(!P)continue;U ve=0,vs=0;unsigned js=P&in[i];while(js){int j=__builtin_ctz(js);js&=js-1;ve+=E[size_t(P)*n+j];}js=P&a[i];while(js){int j=__builtin_ctz(js);js&=js-1;vs+=S[size_t(P)*n+j];}E[size_t(M)*n+i]=ve;S[size_t(M)*n+i]=vs;}}
for(unsigned M=1;M<N-1;M++){unsigned P=(N-1)^M,is=M;while(is){int i=__builtin_ctz(is);is&=is-1;U e=E[size_t(M)*n+i];if(!e)continue;unsigned js=P;while(js){int j=__builtin_ctz(js);js&=js-1;Q[i*n+j]+=e*S[size_t(P)*n+j];}}}
Field f{n,0,std::vector<I>(n*n),std::vector<I>(n)};for(int i=0;i<n;i++)f.h+=E[size_t(N-1)*n+i];for(int i=0;i<n;i++)for(int j=0;j<n;j++){f.C[i*n+j]=I(Q[i*n+j]+Q[j*n+i]);if(a[i]>>j&1)f.A[i]+=f.C[i*n+j];}return f;}
I value(const Field&f,unsigned S){I v=f.h;for(int i=0;i<f.n;i++)if(S>>i&1){v+=f.A[i];for(int j=0;j<i;j++)if(S>>j&1)v-=f.C[i*f.n+j];}return v;}
int main(int argc,char**argv){try{int k=argc>1?std::stoi(argv[1]):6;std::istream*input=&std::cin;std::ifstream file;if(argc>2){file.open(argv[2]);ck(bool(file),"quotient input");input=&file;}unsigned code;unsigned rows=0,classes=0;U presented=0,profiles=0,escapes=0;while(*input>>code){auto T=blow(decode(k,code));U target=count(T);classes++;std::cout<<"Q "<<k<<' '<<code<<" H "<<target<<'\n';for(int block=0;block<k;block++){int r=3*block;std::vector<int>vs;for(int i=0;i<3*k;i++)if(i!=r)vs.push_back(i);int n=vs.size();std::vector<unsigned>B(n);std::vector<int>map(3*k,-1);for(int i=0;i<n;i++)map[vs[i]]=i;for(int i=0;i<n;i++)for(int j=0;j<n;j++)if(T[vs[i]]>>vs[j]&1)B[i]|=1u<<j;Field f=field(B);I g=0;for(I v:f.A)g=std::gcd(g,v);for(I v:f.C)g=std::gcd(g,v);I forced=2;for(int i=0;i<k-3;i++)forced*=3;ck(g%forced==0,"forced divisor");unsigned old=0;for(int i=0;i<n;i++)if(T[r]>>vs[i]&1)old|=1u<<i;ck(value(f,old)==I(target),"original child direct DP");U zcount=0,zprofiles=0,pc=0,weight=0;std::vector<unsigned>zs;
std::function<void(int,unsigned,U)> walk=[&](int b,unsigned cut,U mult){if(b==k){I v=value(f,cut);pc++;weight+=mult;ck((v-I(target))%forced==0,"all profile difference divisor");if(v==I(target)){zcount+=mult;zprofiles++;zs.push_back(cut);}return;}if(b==block){int u=map[3*b+1],v=map[3*b+2];for(int bits=0;bits<4;bits++)walk(b+1,cut|((bits&1)?1u<<u:0)|((bits&2)?1u<<v:0),mult);}else{unsigned bits=0;for(int t=0;t<=3;t++){walk(b+1,cut|bits,mult*((t==1||t==2)?3:1));if(t<3)bits|=1u<<map[3*b+t];}}};walk(0,0,1);ck(weight==(1u<<n),"subset orbit weights complete");rows++;profiles+=pc;presented+=weight;
std::cout<<"ROW "<<block<<" parentH "<<f.h<<" gcd "<<g<<" profiles "<<pc<<" cuts "<<weight<<" zero_profiles "<<zprofiles<<" zero_cuts "<<zcount<<" original "<<old<<" zeros";for(auto z:zs)std::cout<<' '<<z;std::cout<<'\n';if(zcount!=1||zs[0]!=old){escapes++;for(unsigned z:zs){auto child=B;for(int i=0;i<n;i++)if(!(z>>i&1))child[i]|=1u<<n;child.push_back(z);ck(count(child)==target,"escape independently recounted");}}}std::cout.flush();}
std::cout<<"PASS classes "<<classes<<" rows "<<rows<<" profiles "<<profiles<<" represented_cuts "<<presented<<" zero_escape_rows "<<escapes<<'\n';return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
